div.script:
(function(){
  var root=document.getElementById("root");
  var drop=document.getElementById("drop");
  var input=document.getElementById("file");
  var meta=document.getElementById("meta");
  var viewerWrap=document.getElementById("viewer-wrap");
  var viewer=document.getElementById("viewer");
  var placeholder=document.getElementById("placeholder");
  var status=document.getElementById("status");
  var btnClear=document.getElementById("btn-clear");
  var btnCopy=document.getElementById("btn-copy");
  var btnPick=document.getElementById("btn-pick");
  function formatBytes(n){
    if(n<1024)return n+" B";
    if(n<1048576)return(n/1024).toFixed(1)+" KB";
    if(n<1073741824)return(n/1048576).toFixed(2)+" MB";
    return(n/1073741824).toFixed(2)+" GB";
  }
  function escapeHtml(s){
    return String(s).replace(/&/g,"&").replace(//g,">").replace(/"/g,""");
  }
  function setEmpty(){
    meta.textContent="No file loaded";
    viewer.textContent="";
    viewer.style.display="none";
    placeholder.style.display="";
    viewerWrap.classList.add("empty");
    btnClear.disabled=true;
    btnCopy.disabled=true;
    status.textContent="";
    status.className="status";
    input.value="";
  }
  function showText(text,file){
    viewer.textContent=text;
    viewer.style.display="block";
    placeholder.style.display="none";
    viewerWrap.classList.remove("empty");
    btnClear.disabled=false;
    btnCopy.disabled=false;
    var lines=text.length?text.split(/\r\n|\r|\n/).length:0;
    meta.innerHTML=""+escapeHtml(file.name)+" · "+formatBytes(file.size)+" · "+lines.toLocaleString()+" line"+(lines===1?"":"s")+(file.type?" · "+escapeHtml(file.type):"");
    status.textContent="Loaded in browser only — not uploaded anywhere.";
    status.className="status";
  }
  function readFile(file){
    if(!file)return;
    status.textContent="Reading…";
    status.className="status";
    var reader=new FileReader();
    reader.onload=function(){
      try{showText(typeof reader.result==="string"?reader.result:"",file);}
      catch(e){status.textContent="Could not display file: "+(e&&e.message?e.message:e);status.className="status err";}
    };
    reader.onerror=function(){status.textContent="Failed to read file.";status.className="status err";};
    reader.onprogress=function(e){
      if(e.lengthComputable&&e.total>0)status.textContent="Reading… "+Math.round((e.loaded/e.total)*100)+"%";
    };
    reader.readAsText(file);
  }
  function onFiles(files){if(files&&files.length)readFile(files[0]);}
  drop.addEventListener("click",function(){input.click();});
  btnPick.addEventListener("click",function(){input.click();});
  drop.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();input.click();}});
  input.addEventListener("change",function(){onFiles(input.files);});
  ["dragenter","dragover"].forEach(function(ev){
    drop.addEventListener(ev,function(e){e.preventDefault();e.stopPropagation();drop.classList.add("dragover");});
  });
  ["dragleave","drop"].forEach(function(ev){
    drop.addEventListener(ev,function(e){e.preventDefault();e.stopPropagation();drop.classList.remove("dragover");});
  });
  drop.addEventListener("drop",function(e){onFiles(e.dataTransfer&&e.dataTransfer.files);});
  btnClear.addEventListener("click",setEmpty);
  btnCopy.addEventListener("click",function(){
    var text=viewer.textContent||"";
    function done(){btnCopy.textContent="Copied";setTimeout(function(){btnCopy.textContent="Copy all";},1000);}
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(done).catch(function(){fallbackCopy(text);done();});
    }else{fallbackCopy(text);done();}
  });
  function fallbackCopy(text){
    var ta=document.createElement("textarea");
    ta.value=text;ta.style.position="fixed";ta.style.left="-9999px";
    document.body.appendChild(ta);ta.select();
    try{document.execCommand("copy");}catch(e){}
    document.body.removeChild(ta);
  }
})();
